// Generated by APIX. Lets your own backend (a job, a webhook, an agent
// runtime) ask for a payment. It is server-to-server only: callers must send
// the APIX_AGENT_API_SECRET in the Authorization header. The vault contract
// still enforces the limits whoever calls this route.
import { NextResponse } from 'next/server';
import { timingSafeEqual } from 'crypto';
import { payFromVault } from '../../../../lib/near/agent-vault';

function authorized(request: Request): boolean {
  const secret = process.env.APIX_AGENT_API_SECRET;
  const header = request.headers.get('authorization') ?? '';
  if (!secret || secret.length < 32) return false;
  const expected = Buffer.from(`Bearer ${secret}`);
  const given = Buffer.from(header);
  return given.length === expected.length && timingSafeEqual(given, expected);
}

export async function POST(request: Request) {
  if (!authorized(request)) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 });
  }
  let body: { to?: unknown; amountNear?: unknown; memo?: unknown; escalate?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'invalid JSON' }, { status: 400 });
  }
  if (typeof body.to !== 'string' || (typeof body.amountNear !== 'string' && typeof body.amountNear !== 'number')) {
    return NextResponse.json({ error: 'to (string) and amountNear (string) are required' }, { status: 400 });
  }
  try {
    const outcome = await payFromVault({
      to: body.to,
      amountNear: body.amountNear,
      memo: typeof body.memo === 'string' ? body.memo.slice(0, 200) : undefined,
      escalate: body.escalate === true,
    });
    return NextResponse.json(outcome, { status: outcome.status === 'refused' ? 403 : 200 });
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'payment failed' }, { status: 502 });
  }
}
